  const [deltas, setDeltas] = React.useState<string[]>(sourceDeltas)
  const [streaming, setStreaming] = React.useState(false)

  React.useEffect(() => {
    if (!streaming) return

    let index = 0
    setDeltas([])
    const timer = window.setInterval(() => {
      const delta = sourceDeltas[index]
      if (delta === undefined) {
        window.clearInterval(timer)
        setStreaming(false)
        return
      }
      setDeltas((current) => [...current, delta])
      index += 1
      if (index === sourceDeltas.length) {
        window.clearInterval(timer)
        setStreaming(false)
      }
    }, 520)

    return () => window.clearInterval(timer)
  }, [streaming])

  return (
    <div className="mx-auto w-full max-w-xl space-y-4">
      <div className="text-foreground text-sm leading-7">
        <AiStreamDeltas deltas={deltas} isStreaming={streaming} caret />
      </div>
      <Button
        type="button"
        variant="outline"
        size="sm"
        disabled={streaming}
        onClick={() => setStreaming(true)}
      >
        {streaming ? "正在接收 delta…" : "重新播放分段淡入"}
      </Button>
    </div>
  )
}

