"use client"

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { BellIcon, InboxIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"

const rollVariants = {
  enter: (direction: number) => ({ y: `${direction * 100}%`, opacity: 0 }),
  center: { y: "0%", opacity: 1 },
  exit: (direction: number) => ({ y: `${direction * -100}%`, opacity: 0 }),
}

function RollingCount({ value, max = 99 }: { value: number; max?: number }) {
  const reduceMotion = useReducedMotion()
  const previous = React.useRef(value)
  const direction = value >= previous.current ? 1 : -1

  React.useEffect(() => {
    previous.current = value
  }, [value])

  const label = value > max ? `${max}+` : String(value)

  return (
    <span className="relative inline-flex overflow-hidden tabular-nums">
      <AnimatePresence initial={false} mode="popLayout" custom={direction}>
        <motion.span
          key={label}
          custom={direction}
          variants={reduceMotion ? undefined : rollVariants}
          initial="enter"
          animate="center"
          exit="exit"
          transition={{ duration: 0.24, ease: [0.22, 1, 0.36, 1] }}
        >
          {label}
        </motion.span>
      </AnimatePresence>
    </span>
  )
}

export default function BadgeCount() {
  const [count, setCount] = React.useState(3)
  const reduceMotion = useReducedMotion()

  return (
    <div className="flex flex-col items-center gap-6">
      <div className="flex items-center gap-6">
        <div className="relative">
          <Button variant="outline" size="icon" aria-label={`通知，${count} 条未读`}>
            <BellIcon />
          </Button>
          <AnimatePresence>
            {count > 0 ? (
              <motion.span
                className="absolute -top-1.5 -right-1.5"
                initial={reduceMotion ? false : { scale: 0.4, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={reduceMotion ? undefined : { scale: 0.4, opacity: 0 }}
                transition={{ type: "spring", stiffness: 520, damping: 30 }}
              >
                <Badge
                  variant="destructive"
                  size="sm"
                  className="ring-background min-w-4 px-1 ring-2"
                >
                  <RollingCount value={count} />
                </Badge>
              </motion.span>
            ) : null}
          </AnimatePresence>
        </div>

        <div className="flex items-center gap-2 text-sm">
          <InboxIcon className="text-muted-foreground size-4" />
          收件箱
          <Badge variant="secondary">
            <RollingCount value={count * 12} max={999} />
          </Badge>
        </div>
      </div>

      <div className="flex gap-2">
        <Button size="sm" variant="outline" onClick={() => setCount((c) => Math.max(0, c - 1))}>
          标记一条已读
        </Button>
        <Button size="sm" onClick={() => setCount((c) => c + 1)}>
          收到新消息
        </Button>
      </div>
    </div>
  )
}

bubble-conversation.code:
"use client"

import * as React from "react"
import { ArrowUpIcon, HeadsetIcon } from "lucide-react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Bubble,
  BubbleAvatar,
  BubbleBody,
  BubbleContent,
  BubbleFooter,
  BubbleTyping,
} from "@/components/ui/bubble"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"

type Message = {
  id: number
  side: "start" | "end"
  text: string
  time: string
}

const replies = [
  "已查到订单 #20931，包裹今天 09:12 从杭州转运中心发出，预计明天中午前送达。",
  "可以的，我已为你备注「放丰巢快递柜」，派送员出发前会再发短信确认。",
  "不客气！如果还需要改地址或开发票，直接在这里告诉我就好。",
]

const suggestions = ["我的快递到哪了？", "能放快递柜吗？", "好的，谢谢"]

function now() {
  return new Date().toLocaleTimeString("zh-CN", {
    hour: "2-digit",
    minute: "2-digit",
  })
}

export default function BubbleConversation() {
  const [messages, setMessages] = React.useState<Message[]>([
    {
      id: 0,
      side: "start",
      text: "你好，我是售后助理小川，有什么可以帮你？",
      time: "10:02",
    },
  ])
  const [draft, setDraft] = React.useState("")
  const [typing, setTyping] = React.useState(false)
  const replyIndex = React.useRef(0)
  const nextId = React.useRef(1)
  const timer = React.useRef<number | undefined>(undefined)
  const listRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => () => window.clearTimeout(timer.current), [])

  React.useEffect(() => {
    const list = listRef.current
    if (!list) return
    list.scrollTo({ top: list.scrollHeight, behavior: "smooth" })
  }, [messages.length, typing])

  function send(text: string) {
    const content = text.trim()
    if (!content || typing) return

    setMessages((current) => [
      ...current,
      { id: nextId.current++, side: "end", text: content, time: now() },
    ])
    setDraft("")
    setTyping(true)

    window.clearTimeout(timer.current)
    timer.current = window.setTimeout(() => {
      const reply = replies[replyIndex.current % replies.length]
      replyIndex.current += 1
      setTyping(false)
      setMessages((current) => [
        ...current,
        { id: nextId.current++, side: "start", text: reply, time: now() },
      ])
    }, 1200)
  }

  return (
    <div className="mx-auto flex w-full max-w-md flex-col overflow-hidden rounded-lg border bg-background">
      <header className="flex items-center gap-2.5 border-b px-4 py-3">
        <Avatar size="sm">
          <AvatarFallback className="bg-primary/10 text-primary">
            <HeadsetIcon className="size-4" />
          </AvatarFallback>
        </Avatar>
        <div className="min-w-0">
          <p className="text-sm font-medium leading-5">售后助理 · 小川</p>
          <p className="text-muted-foreground text-xs">
            {typing ? "正在输入…" : "通常 1 分钟内回复"}
          </p>
        </div>
      </header>

      <div
        ref={listRef}
        role="log"
        className="flex h-80 flex-col gap-4 overflow-y-auto px-4 py-4"
      >
        {messages.map((message) => (
          <Bubble key={message.id} side={message.side}>
            {message.side === "start" ? (
              <BubbleAvatar>
                <Avatar size="sm">
                  <AvatarFallback className="bg-primary/10 text-primary">
                    川
                  </AvatarFallback>
                </Avatar>
              </BubbleAvatar>
            ) : null}
            <BubbleBody>
              <BubbleContent
                variant={message.side === "end" ? "primary" : "default"}
              >
                {message.text}
              </BubbleContent>
              <BubbleFooter>
                <time>{message.time}</time>
              </BubbleFooter>
            </BubbleBody>
          </Bubble>
        ))}

        {typing ? (
          <Bubble>
            <BubbleAvatar>
              <Avatar size="sm">
                <AvatarFallback className="bg-primary/10 text-primary">
                  川
                </AvatarFallback>
              </Avatar>
            </BubbleAvatar>
            <BubbleBody>
              <BubbleContent className="text-muted-foreground">
                <BubbleTyping label="小川正在输入" />
              </BubbleContent>
            </BubbleBody>
          </Bubble>
        ) : null}
      </div>

      <div className="flex flex-wrap gap-1.5 border-t px-4 pt-3">
        {suggestions.map((item) => (
          <Button
            key={item}
            type="button"
            size="sm"
            variant="outline"
            className="h-7 rounded-full px-2.5 text-xs font-normal"
            disabled={typing}
            onClick={() => send(item)}
          >
            {item}
          </Button>
        ))}
      </div>

      <form
        className="flex items-center gap-2 px-4 pb-4 pt-2.5"
        onSubmit={(event) => {
          event.preventDefault()
          send(draft)
        }}
      >
        <Input
          aria-label="输入消息"
          placeholder="输入消息，回车发送"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
        />
        <Button
          type="submit"
          size="icon"
          className="size-10 shrink-0"
          aria-label="发送"
          disabled={!draft.trim() || typing}
        >
          <ArrowUpIcon />
        </Button>
      </form>
    </div>
  )
}

