form-layout.code:
"use client"

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { GlobeIcon, ServerIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Form,
  FormActions,
  FormControl,
  FormDescription,
  FormField,
  FormLabel,
  FormLegend,
  FormSection,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import { InputNumber } from "@/components/ui/input-number"
import { Switch } from "@/components/ui/switch"

const initialConfig = {
  name: "checkout-api",
  region: "cn-shanghai",
  maxReplicas: 12 as number | null,
  https: true,
  autoScaling: true,
}

export default function FormLayout() {
  const reduceMotion = useReducedMotion()
  const [config, setConfig] = React.useState(initialConfig)
  const [saved, setSaved] = React.useState(false)
  const dirty = JSON.stringify(config) !== JSON.stringify(initialConfig)

  function patch(next: Partial<typeof initialConfig>) {
    setConfig((current) => ({ ...current, ...next }))
    setSaved(false)
  }

  return (
    <Form
      className="w-full max-w-2xl"
      onSubmit={(event) => {
        event.preventDefault()
        setSaved(true)
      }}
    >
      <FormSection>
        <FormLegend>服务配置</FormLegend>
        <p className="text-muted-foreground -mt-2 text-sm">
          修改后需要重新部署才会生效。
        </p>

        <div className="grid gap-4 sm:grid-cols-2">
          <FormField required>
            <FormLabel>服务名称</FormLabel>
            <FormControl>
              <Input
                value={config.name}
                onChange={(event) => patch({ name: event.target.value })}
                startContent={<ServerIcon />}
              />
            </FormControl>
            <FormDescription>小写字母、数字与连字符</FormDescription>
          </FormField>

          <FormField required>
            <FormLabel>部署地域</FormLabel>
            <FormControl>
              <Input
                value={config.region}
                onChange={(event) => patch({ region: event.target.value })}
                startContent={<GlobeIcon />}
              />
            </FormControl>
            <FormDescription>建议选择离用户最近的地域</FormDescription>
          </FormField>
        </div>

        <FormField className="sm:max-w-[calc(50%-0.5rem)]">
          <FormLabel>最大副本数</FormLabel>
          <FormControl>
            <InputNumber
              value={config.maxReplicas}
              onValueChange={(maxReplicas) => patch({ maxReplicas })}
              min={1}
              max={50}
              suffix="个"
            />
          </FormControl>
          <FormDescription>流量高峰时最多扩容到的实例数量</FormDescription>
        </FormField>
      </FormSection>

      <FormSection className="gap-0 divide-y border-y">
        {(
          [
            {
              key: "https",
              title: "强制 HTTPS",
              description: "自动签发证书，并将 HTTP 请求重定向到 HTTPS",
            },
            {
              key: "autoScaling",
              title: "弹性伸缩",
              description: "CPU 使用率持续 5 分钟高于 80% 时自动扩容",
            },
          ] as const
        ).map((item) => (
          <div key={item.key} className="flex items-center justify-between gap-6 py-3.5">
            <label htmlFor={`config-${item.key}`} className="grid cursor-pointer gap-1">
              <span className="text-sm font-medium leading-none">{item.title}</span>
              <span className="text-muted-foreground text-xs">{item.description}</span>
            </label>
            <Switch
              id={`config-${item.key}`}
              checked={config[item.key]}
              onCheckedChange={(checked) => patch({ [item.key]: checked })}
            />
          </div>
        ))}
      </FormSection>

      <FormActions>
        <AnimatePresence initial={false}>
          {saved ? (
            <motion.span
              key="saved"
              className="text-success mr-auto text-xs font-medium"
              initial={reduceMotion ? false : { opacity: 0, y: 4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
            >
              配置已保存，将在下次部署时生效
            </motion.span>
          ) : null}
        </AnimatePresence>
        <Button
          type="button"
          variant="ghost"
          disabled={!dirty}
          onClick={() => {
            setConfig(initialConfig)
            setSaved(false)
          }}
        >
          撤销修改
        </Button>
        <Button type="submit" disabled={!dirty || saved}>
          保存配置
        </Button>
      </FormActions>
    </Form>
  )
}

form-controlled.code:
"use client"

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { CheckCircle2Icon, KeyRoundIcon, Loader2Icon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Form,
  FormActions,
  FormControl,
  FormDescription,
  FormField,
  FormLabel,
  FormMessage,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"

type Status = "idle" | "loading" | "success" | "error"

export default function FormControlled() {
  const reduceMotion = useReducedMotion()
  const [apiKey, setApiKey] = React.useState("")
  const [status, setStatus] = React.useState<Status>("idle")
  const [errorMessage, setErrorMessage] = React.useState("")

  function verify(event: React.FormEvent) {
    event.preventDefault()
    if (!apiKey.startsWith("sk-")) {
      setStatus("error")
      setErrorMessage("密钥格式不正确，应以 sk- 开头")
      return
    }

    setStatus("loading")
    setTimeout(() => {
      if (apiKey.length < 16) {
        setStatus("error")
        setErrorMessage("密钥无效或已被吊销，请在控制台重新生成")
      } else {
        setStatus("success")
      }
    }, 1200)
  }

  return (
    <Form onSubmit={verify} className="w-full max-w-md">
      <FormField invalid={status === "error"} required>
        <FormLabel>API 密钥</FormLabel>
        <FormControl>
          <Input
            type="password"
            placeholder="sk-••••••••••••••••"
            autoComplete="off"
            value={apiKey}
            startContent={<KeyRoundIcon />}
            onChange={(event) => {
              setApiKey(event.target.value)
              if (status !== "idle" && status !== "loading") setStatus("idle")
            }}
            readOnly={status === "loading"}
          />
        </FormControl>
        <FormMessage>{errorMessage}</FormMessage>
        <FormDescription>密钥只保存在当前浏览器会话中，不会上传到服务器。</FormDescription>
      </FormField>

      <FormActions className="justify-between">
        <AnimatePresence initial={false}>
          {status === "success" ? (
            <motion.span
              key="success"
              className="text-success flex items-center gap-1.5 text-xs font-medium"
              initial={reduceMotion ? false : { opacity: 0, x: -6 }}
              animate={{ opacity: 1, x: 0 }}
              exit={reduceMotion ? { opacity: 0 } : { opacity: 0, x: -6 }}
              transition={{ duration: reduceMotion ? 0 : 0.2 }}
            >
              <CheckCircle2Icon className="size-4" />
              验证通过，已绑定到当前项目
            </motion.span>
          ) : (
            <span key="placeholder" />
          )}
        </AnimatePresence>
        <Button type="submit" disabled={status === "loading" || !apiKey}>
          {status === "loading" ? <Loader2Icon className="animate-spin" /> : null}
          {status === "loading" ? "正在验证" : "验证并绑定"}
        </Button>
      </FormActions>
    </Form>
  )
}

