        <SmoothScroll
          root={false}
          options={{ lerp: 0.08, wheelMultiplier: 0.9 }}
          className="h-[24rem] overflow-y-auto"
        >
          <LenisProgress />
          <Feed />
        </SmoothScroll>
      </div>
    </div>
  )
}

