  const [staggerFrom, setStaggerFrom] =
    React.useState<Exclude<TextRotateStaggerFrom, number>>("first")
  const [direction, setDirection] = React.useState<"up" | "down">("up")
  const [blur, setBlur] = React.useState(false)

