            variant={compact ? "secondary" : "ghost"}
            size="sm"
            onClick={() => setCompact((value) => !value)}
          >
            <SlidersHorizontal />
            <span className="hidden sm:inline">紧凑</span>
          </Button>
          {filterActive ? (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={resetFilters}
            >
              <X />
              清除
