            <TableHead aria-sort={ariaSort(sort, "due")} className="w-[92px] border-r">
              <SortLabel
                label="截止"
                column="due"
                sort={sort}
                onSort={toggleSort}
              />
            </TableHead>
            <TableHead className="w-[110px]">状态</TableHead>
            <TableHead aria-sort={ariaSort(sort, "progress")} className="w-[150px] border-r">
              <SortLabel
                label="进度"
                column="progress"
                sort={sort}
                onSort={toggleSort}
              />
            </TableHead>
          </TableRow>
          <TableRow className="bg-background hover:bg-background">
            <TableHead pinned="left" className="bg-background w-11 px-3" />
            <TableHead
              pinned="left"
              pinOffset={44}
              className="bg-background w-9 px-2"
            />
            <TableHead
              pinned="left"
              pinOffset={80}
              className="bg-background px-2"
            >
              <input
                aria-label="按名称筛选"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="筛选名称…"
                className="text-foreground placeholder:text-muted-foreground focus:border-foreground h-7 w-full border-b bg-transparent px-1 text-xs outline-none"
              />
            </TableHead>
            <TableHead className="px-2">
              <select
                aria-label="按负责人筛选"
                value={owner}
                onChange={(event) => setOwner(event.target.value)}
                className="text-foreground focus:border-foreground h-7 w-full border-b bg-transparent text-xs outline-none"
              >
                <option value="all">全部负责人</option>
                <option value="林澈">林澈</option>
                <option value="沈言">沈言</option>
                <option value="周屿">周屿</option>
                <option value="唐可">唐可</option>
              </select>
            </TableHead>
            <TableHead className="text-muted-foreground px-2 text-xs">
              —
            </TableHead>
            <TableHead className="text-muted-foreground border-r px-2 text-xs">
              —
            </TableHead>
            <TableHead className="px-2">
              <select
                aria-label="按状态筛选"
                value={status}
                onChange={(event) => setStatus(event.target.value)}
                className="text-foreground focus:border-foreground h-7 w-full border-b bg-transparent text-xs outline-none"
              >
                <option value="all">全部状态</option>
                <option value="进行中">进行中</option>
                <option value="待开始">待开始</option>
                <option value="有风险">有风险</option>
                <option value="已完成">已完成</option>
              </select>
            </TableHead>
            <TableHead className="text-muted-foreground border-r px-2 text-xs">
              —
            </TableHead>
            <TableHead pinned="right" className="bg-background px-2 text-right">
              <span className="text-muted-foreground text-xs">固定列</span>
            </TableHead>
          </TableRow>
        </TableHeader>

        <TableBody>
          {flatRows.map(({ item, depth }) => {
            const hasChildren = Boolean(item.children?.length)
            const isExpanded = expanded.has(item.id)

            return (
              <TableRow
                key={item.id}
                draggable
                data-dragging={draggingId === item.id}
                data-state={selected.has(item.id) ? "selected" : undefined}
                className={cn(
                  depth > 0 &&
                    "animate-in fade-in-0 slide-in-from-top-1 duration-200 motion-reduce:animate-none"
                )}
                onPointerDownCapture={(event) => {
                  dragHandleRef.current = (event.target as HTMLElement).closest(
                    "[data-slot=table-drag-handle]"
                  )
                    ? item.id
                    : null
                }}
                onDragStart={(event) => {
                  if (dragHandleRef.current !== item.id) {
                    event.preventDefault()
                    return
                  }
                  setDraggingId(item.id)
                  event.dataTransfer.effectAllowed = "move"
                }}
                onDragEnd={() => {
                  dragHandleRef.current = null
                  setDraggingId(null)
                }}
                onDragOver={(event) => {
                  if (draggingId && draggingId !== item.id) {
                    event.preventDefault()
                    event.dataTransfer.dropEffect = "move"
                  }
                }}
                onDrop={(event) => {
                  event.preventDefault()
                  if (draggingId && draggingId !== item.id) {
                    setRows((current) =>
                      moveWithinLevel(current, draggingId, item.id)
                    )
                    setSort(null)
                  }
                  dragHandleRef.current = null
                  setDraggingId(null)
                }}
              >
                <TableCell pinned="left" className="w-11 px-3 text-center">
                  <Checkbox
                    size="sm"
                    aria-label={`选择${item.name}`}
                    checked={selected.has(item.id)}
