                  />
                </TableCell>
                <TableCell
                  pinned="left"
                  pinOffset={44}
                  className="text-muted-foreground w-9 px-2"
                >
                  <button
                    type="button"
                    data-slot="table-drag-handle"
                    className="hover:text-foreground focus-visible:ring-ring/40 cursor-grab touch-none p-1 outline-none focus-visible:ring-2 active:cursor-grabbing"
                    aria-label={`拖动${item.name}`}
                  >
                    <GripVertical className="size-4" />
                  </button>
                </TableCell>
                <TableCell
                  pinned="left"
                  pinOffset={80}
                  className="w-[260px] font-medium"
                >
                  <div
                    className="flex items-center gap-1.5"
                    style={{ paddingInlineStart: depth * 20 }}
                  >
                    {hasChildren ? (
                      <button
                        type="button"
                        className="text-muted-foreground hover:text-foreground focus-visible:ring-ring/40 flex size-6 shrink-0 items-center justify-center outline-none focus-visible:ring-2"
                        aria-label={isExpanded ? `收起${item.name}` : `展开${item.name}`}
                        aria-expanded={isExpanded || filterActive}
                        onClick={() =>
                          setExpanded((current) => {
                            const next = new Set(current)
                            next.has(item.id)
                              ? next.delete(item.id)
                              : next.add(item.id)
                            return next
                          })
                        }
                      >
                        <ChevronRight
                          className={cn(
                            "size-4 transition-transform duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none",
                            (isExpanded || filterActive) && "rotate-90"
                          )}
                        />
                      </button>
                    ) : (
                      <span className="size-6 shrink-0" />
                    )}
                    <span>{item.name}</span>
                    {hasChildren ? (
                      <span className="text-muted-foreground text-[11px] font-normal">
                        {item.children?.length}
                      </span>
                    ) : null}
                  </div>
                </TableCell>
                <TableCell>{item.owner}</TableCell>
                <TableCell className="text-muted-foreground tabular-nums">
                  {item.start}
                </TableCell>
                <TableCell className="border-r tabular-nums">
                  {item.due}
                </TableCell>
                <TableCell>
                  <span
                    className={cn(
                      "inline-flex px-2 py-1 text-xs font-medium",
                      statusStyles[item.status]
                    )}
                  >
                    {item.status}
                  </span>
                </TableCell>
                <TableCell className="border-r">
                  <div className="flex items-center gap-2">
                    <div className="bg-muted h-1.5 w-20 overflow-hidden">
                      <div
                        className={cn(
                          "h-full",
                          item.status === "有风险"
                            ? "bg-warning"
                            : "bg-foreground/70"
                        )}
                        style={{ width: `${item.progress}%` }}
                      />
                    </div>
                    <span className="text-muted-foreground w-8 text-right text-xs tabular-nums">
                      {item.progress}%
                    </span>
                  </div>
                </TableCell>
                <TableCell
                  pinned="right"
                  className="w-[120px] text-right font-medium tabular-nums"
                >
                  ¥{item.budget.toLocaleString("zh-CN")}
                </TableCell>
              </TableRow>
            )
          })}
          {flatRows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={9}
                className="text-muted-foreground animate-in fade-in-0 h-32 text-center duration-300"
              >
                没有符合当前筛选条件的工作项
              </TableCell>
            </TableRow>
          ) : null}
        </TableBody>
      </Table>
      <p className="text-muted-foreground mt-2 text-xs">
        拖动手柄可在同级内排序；横向滚动时，选择、拖动、名称和预算列保持固定。
      </p>
    </div>
  )
}

